def reverse_mapping(module, name):
    if (module, name) in REVERSE_NAME_MAPPING:
        (module, name) = REVERSE_NAME_MAPPING[module, name]
    elif module in REVERSE_IMPORT_MAPPING:
        module = REVERSE_IMPORT_MAPPING[module]
    return (module, name)

