    def test_reentrancy(self):
        q = self.q
        gen = itertools.count()
        N = 10000
        results = []

        class Circular(object):

            def __init__(self):
                self.circular = self

            def __del__(self):
                q.put(next(gen))
        while True:
            o = Circular()
            q.put(next(gen))
            del o
            results.append(q.get())
            if results[-1] >= N:
                break
        self.assertEqual(results, list(range(N + 1)))

