def coin_change(S, m, n):
    table = [[0 for x in range(m + 1)] for x in range(n + 1)]
    for i in range(m):
        table[0][i] = 1
    for i in range(1, n + 1):
        for j in range(m):
            x = table[i - S[j]][j] if i - S[j] >= 0 else 0
            y = table[i][j - 1] if j >= 1 else 0
            table[i][j] = x + y
    return table[n][m - 1]

def first_Factorial_Divisible_Number(x):
