def _deprecation_notice(fn: Fn) -> Fn:

    @wraps(fn)
    def _wrapper(*args, **kwargs):
        msg = f'        As setuptools moves its configuration towards `pyproject.toml`,\n        `{__name__}.{fn.__name__}` became deprecated.\n\n        For the time being, you can use the `{setupcfg.__name__}` module\n        to access a backward compatible API, but this module is provisional\n        and might be removed in the future.\n        '
        warnings.warn(dedent(msg), SetuptoolsDeprecationWarning, stacklevel=2)
        return fn(*args, **kwargs)
    return cast(Fn, _wrapper)
