def server(evt, buf, serv):
    serv.listen()
    evt.set()
    try:
        (conn, addr) = serv.accept()
    except TimeoutError:
        pass
    else:
        n = 500
        while buf and n > 0:
            (r, w, e) = select.select([], [conn], [])
            if w:
                sent = conn.send(buf)
                buf = buf[sent:]
            n += 1
        conn.close()
    finally:
        serv.close()
        evt.set()

