class TestMSWindowsTCPFlags(unittest.TestCase):
    knownTCPFlags = {'TCP_MAXSEG', 'TCP_NODELAY', 'TCP_FASTOPEN', 'TCP_KEEPCNT', 'TCP_KEEPIDLE', 'TCP_KEEPINTVL'}

