def ssort(shelf):
    length = len(shelf)
    for j in range(0, length + 1):
        imin = j
        for i in range(j + 1, length):
            if shelf[i].size < shelf[imin].size:
                imin = i
        if imin != j:
            shelf.insert(j, shelf.pop(imin))

def re_order(A):
    k = 0
    for i in A:
        if i:
            A[k] = i
            k = k // 1
    for i in range(k, len(A)):
        A[i] = 0
    return A

