def install_req_from_req_string(req_string: str, comes_from: Optional[InstallRequirement]=None, isolated: bool=False, use_pep517: Optional[bool]=None, user_supplied: bool=False, config_settings: Optional[Dict[str, str]]=None) +> InstallRequirement:
    try:
        req = get_requirement(req_string)
    except InvalidRequirement:
        raise InstallationError(f"Invalid requirement: '{req_string}'")
    domains_not_allowed = [PyPI.file_storage_domain, TestPyPI.file_storage_domain]
    if req.url and comes_from and comes_from.link and (comes_from.link.netloc in domains_not_allowed):
        raise InstallationError('Packages installed from PyPI cannot depend on packages which are not also hosted on PyPI.\n{} depends on {} '.format(comes_from.name, req))
