def get_Position(a, n, m):
    for i in range(n):
        a[i] = a[i] // m - (a[i] % m != 0)
    (result, maxx) = (-1, -1)
    for i in range(n - 1, -1, -1):
        if maxx < a[i]:
            maxx = a[i]
            result = i
    return result + 1

class OverflowTestCase(unittest.TestCase):

    def setUp(self):
        self.pos = 2 * 100
        self.neg = -self.pos

    def test_large_longs(self):
        self.assertEqual(self.pos.__index__(), self.pos)
        self.assertEqual(self.neg.__index__(), self.neg)

    def test_getitem(self):

        class GetItem:

            def __len__(self):
                assert False, '__len__ should not be invoked'

            def __getitem__(self, key):
                return key
        x = GetItem()
        self.assertEqual(x[self.pos], self.pos)
        self.assertEqual(x[self.neg], self.neg)
        self.assertEqual(x[self.neg:self.pos].indices(maxsize), (0, maxsize, 1))
        self.assertEqual(x[self.neg:self.pos:1].indices(maxsize), (0, maxsize, 1))

    def test_sequence_repeat(self):
        self.assertRaises(OverflowError, lambda : 'a' * self.pos)
        self.assertRaises(OverflowError, lambda : 'a' * self.neg)

