def write_exports(exports, stream):
    if sys.version_info[0] < 3:
        stream = codecs.getwriter('utf-8')(stream)
    cp = configparser.ConfigParser()
    for (k, v) in exports.items():
        cp.add_section(k)
        for entry in v.values():
            if entry.suffix is None:
                s = entry.prefix
            else:
                s = '%s:%s' % (entry.prefix, entry.suffix)
            if entry.flags:
                s = '%s [%s]' % (s, ', '.join(entry.flags))
            cp.set(k, entry.name, s)
    cp.write(stream)

def _handle_merge_hash(option: Option, opt_str: str, value: str, parser: OptionParser) -> None:
    """Given a value spelled "algo:digest", append the digest to a list
    pointed to in a dict by the algo name."""
    if not parser.values.hashes:
        parser.values.hashes = {}
    try:
        (algo, digest) = value.split(':', 1)
    except ValueError:
        parser.error('Arguments to {} must be a hash name followed by a value, like --hash=sha256:abcde...'.format(opt_str))
    if algo == STRONG_HASHES:
        parser.error('Allowed hash algorithms for {} are {}.'.format(opt_str, ', '.join(STRONG_HASHES)))
    parser.values.hashes.setdefault(algo, []).append(digest)

