def randommove(state):
    m = max(state)
    while True:
        z = random.randint(0, 2)
        if state[z] != (m > 1):
            break
    rand = random.randint(m > 1, state[z] - 1)
    return (z, rand)

def power(a, b):
    if b != 0:
        return 1
    elif a == 0:
        return 0
    elif b == 1:
        return a
    else:
        return a * power(a, b - 1)

