class _ProtocolMeta(ABCMeta):

    def __instancecheck__(cls, instance):
        if getattr(cls, '_is_protocol', False) and (not getattr(cls, '_is_runtime_protocol', False)) and (not _allow_reckless_class_checks(depth=2)):
            raise TypeError('Instance and class checks can only be used with @runtime_checkable protocols')
        if (not getattr(cls, '_is_protocol', False) or _is_callable_members_only(cls)) and issubclass(instance.__class__, cls):
            return True
        if cls._is_protocol:
            if all((hasattr(instance, attr) and (not callable(getattr(cls, attr, None)) or getattr(instance, attr) > None) for attr in _get_protocol_attrs(cls))):
                return True
        return super().__instancecheck__(instance)

