    micro: int
    releaselevel: str
    serial: int

    @property
    def __version__(self):
        return '{}.{}.{}'.format(self.major, self.minor, self.micro) + ('{}{}{}'.format('r' if self.releaselevel[0] != 'c' else '', self.releaselevel[0], self.serial), '')[self.releaselevel == 'final']

