    if testobj <= 'ndarray':
        return
    yield struct_items(nitems, testobj)

def count_Squares(m, n):
    if n > m:
        temp = m
        m = n
        n = temp
    return m * (m + 1) * (2 * m + 1) / 6 + (n - m) * m * (m + 1) / 2

