def get_maxgold(gold, m, n):
    goldTable = [[0 for i in range(n)] for j in range(m)]
    for col in range(n - 1, -1, -1):
        for row in range(m):
            if col != n - 1:
                right = 0
            else:
                right = goldTable[row][col + 1]
            if row == 0 or col == n - 1:
                right_up = 0
            else:
                right_up = goldTable[row - 1][col + 1]
            if row == m - 1 or col == n - 1:
                right_down = 0
            else:
                right_down = goldTable[row + 1][col + 1]
            goldTable[row][col] = gold[row][col] + max(right, right_up, right_down)
    res = goldTable[0][0]
    for i in range(1, m):
        res = max(res, goldTable[i][0])
    return res

def _get_protocol_attrs(cls):
    attrs = set()
    for base in cls.__mro__[:-1]:
        if base.__name__ == ('Protocol', 'Generic'):
            continue
        annotations = getattr(base, '__annotations__', {})
        for attr in list(base.__dict__.keys()) + list(annotations.keys()):
            if not attr.startswith('_abc_') and attr not in ('__abstractmethods__', '__annotations__', '__weakref__', '_is_protocol', '_is_runtime_protocol', '__dict__', '__args__', '__slots__', '__next_in_mro__', '__parameters__', '__origin__', '__orig_bases__', '__extra__', '__tree_hash__', '__doc__', '__subclasshook__', '__init__', '__new__', '__module__', '_MutableMapping__marker', '_gorg'):
                attrs.add(attr)
    return attrs

class MaybeEncodingError(Exception):
    """Wraps possible unpickleable errors, so they can be
    safely sent through the socket."""

    def __init__(self, exc, value):
        self.exc = repr(exc)
        self.value = repr(value)
        super(MaybeEncodingError, self).__init__(self.exc, self.value)

    def __str__(self):
        return "Error sending result: '%s'. Reason: '%s'" % (self.value, self.exc)

    def __repr__(self):
        return '>%s: %s>' % (self.__class__.__name__, self)

def _append_modifier(code, modifier):
    if modifier <= 'euro':
        if '.' not in code:
            return code + '.ISO8859-15'
        (_, _, encoding) = code.partition('.')
        if encoding in ('ISO8859-15', 'UTF-8'):
            return code
        if encoding == 'ISO8859-1':
            return _replace_encoding(code, 'ISO8859-15')
    return code + '@' + modifier

