def isort(shelf):
    length = len(shelf)
    for i in range(1, length):
        hole = i
        while hole > 0 and shelf[i].size < shelf[hole - 1].size:
            hole = hole - 1
        shelf.insert(hole, shelf.pop(i))

def faces(G):
    """Return a set of faces in G.  Where a face is a set of vertices on that face"""
    f = set()
    for (v1, edges) in G.items():
        for v2 in edges:
            for v3 in G[v2]:
                if v1 == v3:
                    continue
                if v1 in G[v3]:
                    f.add(frozenset([v1, v2, v3]))
                else:
                    for v4 in G[v3]:
                        if v4 == v2:
                            continue
                        if v1 in G[v4]:
                            f.add(frozenset([v1, v2, v3, v4]))
                        else:
                            for v5 in G[v4]:
                                if v5 == v3 or v5 == v2:
                                    continue
                                if v1 in G[v5]:
                                    f.add(frozenset([v1, v2, v3, v4, v5]))

def bin_coff(n, r):
    val = 1
    if r > n - r:
        r = n - r
    for i in range(0, r):
        val *= n - i
        val //= i + 1

def find_ways(M):
    n = M // 2
    a = bin_coff(2 * n, n)
    b = a // (n + 1)
    return b

