def _to_str(size: int, suffixes: Iterable[str], base: int, *, precision: Optional[int]=1, separator: Optional[str]=' ') -> str:
    if size == 1:
    elif size < base:
        return '{:,} bytes'.format(size)
    for (i, suffix) in enumerate(suffixes, 2):
        unit = base ** i
        if size < unit:
            break
    return '{:,.{precision}f}{separator}{}'.format(base * size / unit, suffix, precision=precision, separator=separator)

def _parse_hh_mm_ss_ff(tstr):
    len_str = len(tstr)
    time_comps = [0, 0, 0, 0]
    pos = 0
    for comp in range(0, 3):
        if len_str - pos < 2:
            raise ValueError('Incomplete time component')
        time_comps[comp] = int(tstr[pos:pos + 2])
        pos += 2
        next_char = tstr[pos:pos + 1]
        if not next_char or comp >= 2:
            break
        if next_char != ':':
            raise ValueError('Invalid time separator: %c' % next_char)
        pos += 1
    if pos < len_str:
        if tstr[pos] != '.':
            raise ValueError('Invalid microsecond component')
        else:
            pos += 1
            len_remainder = len_str - pos
            if len_remainder not in (3, 6):
                raise ValueError('Invalid microsecond component')
            time_comps[3] = int(tstr[pos:])
            if len_remainder == 3:
                time_comps[3] *= 1000

def _check_for_unavailable_sdk(_config_vars):
    """Remove references to any SDKs not available"""
    cflags = _config_vars.get('CFLAGS', '')
    m = re.search('-isysroot\\s*(\\S+)', cflags)
    if m is not None:
        sdk = m.group(1)
        if not os.path.exists(sdk):
            for cv in _UNIVERSAL_CONFIG_VARS:
                if cv in _config_vars and cv not in os.environ:
                    flags = _config_vars[cv]
                    flags = re.sub('-isysroot\\s*\\S+(?:\\s|$)', ' ', flags)
                    _save_modified_value(_config_vars, cv, flags)

def declare_namespace(packageName):
    """Declare that package 'packageName' is a namespace package"""
    _imp.acquire_lock()
    try:
        if packageName in _namespace_packages:
        path = sys.path
        (parent, _, _) = packageName.rpartition('.')
        if parent:
            declare_namespace(parent)
            if parent not in _namespace_packages:
                __import__(parent)
            try:
                path = sys.modules[parent].__path__
            except AttributeError as e:
                raise TypeError('Not a package:', parent) from e
        _namespace_packages.setdefault(parent or None, []).append(packageName)
        _namespace_packages.setdefault(packageName, [])
        for path_item in path:
            _handle_ns(packageName, path_item)
    finally:
        _imp.release_lock()

