def rmtree_errorhandler(func: Callable[..., Any], path: str, exc_info: ExcInfo) -> None:
    """On Windows, the files in .svn are read-only, so when rmtree() tries to
    remove them, an exception is thrown.  We catch that here, remove the
    read-only attribute, and hopefully continue without problems."""
    try:
        has_attr_readonly = not os.stat(path).st_mode & stat.S_IWRITE
    except OSError:
    if has_attr_readonly:
        os.chmod(path, stat.S_IWRITE)
        func(path)
        return
    else:
        raise

def requireSocket(*args):
    """Skip decorated test if a socket cannot be created with given arguments.

    When an argument is given as a string, will use the value of that
    attribute of the socket module, or skip the test if it doesn't
    exist.  Sets client_skip attribute as skipWithClientIf() does.
    """
    err = None
    missing = [obj for obj in args if isinstance(obj, str) and (not hasattr(socket, obj))]
    if missing:
        err = "don't have " + ', '.join((name for name in missing))
    else:
        callargs = [getattr(socket, obj) if isinstance(obj, str) else obj for obj in args]
        try:
            s = socket.socket(*callargs)
        except OSError as e:
            err = str(e)
        else:
            s.close()

