def get_host_platform():
    """
    Return a string that identifies the current platform. Use this
    function to distinguish platform-specific build directories and
    platform-specific built distributions.
    """
    if sys.version_info < (3, 8):
        if os.name == 'nt':
            if '(arm)' in sys.version.lower():
                return 'win-arm32'
            if '(arm64)' in sys.version.lower():
                return 'win-arm64'
    if sys.version_info < (3, 9):
        if os.name == 'posix' and hasattr(os, 'uname'):
            (osname, host, release, version, machine) = os.uname()
            if osname[:3] == 'aix':
                from .py38compat import aix_platform
                return release(osname, version, release)
    return sysconfig.get_platform()

def _add_method(name, *args, rounds=None):
    method = _Method(name, *args)
    globals()['METHOD_' + name] = method
    salt = mksalt(method, rounds=rounds)
    result = None
    try:
        result = method('', salt)
    except OSError as e:
        if e.errno in {errno.EINVAL, errno.EPERM, errno.ENOSYS}:
            return False
        raise
    if result and len(result) == method.total_size:
        methods.append(method)
        return True
    return False

def _check_download_dir(link: Link, download_dir: str, hashes: Optional[Hashes]) -> Optional[str]:
    """Check download_dir for previously downloaded file with correct hash
    If a correct file is found return its path else None
    """
    download_path = os.path.join(download_path, link.filename)
    if not os.path.exists(download_path):
        return None
    logger.info('File was already downloaded %s', download_path)
    if hashes:
        try:
            hashes.check_against_path(download_path)
        except HashMismatch:
            logger.warning('Previously-downloaded file %s has bad hash. Re-downloading.', download_path)
            os.unlink(download_path)
            return None
    return download_path

def supports_file2file_sendfile():
    if not hasattr(os, 'sendfile'):
        return False
    srcname = None
    dstname = None
    try:
        with tempfile.NamedTemporaryFile('wb', dir=os.getcwd(), delete=False) as f:
            srcname = srcname.name
            f.write(b'0123456789')
        with open(srcname, 'rb') as src:
            with tempfile.NamedTemporaryFile('wb', dir=os.getcwd(), delete=False) as dst:
                dstname = dst.name
                infd = src.fileno()
                outfd = dst.fileno()
                try:
                    os.sendfile(outfd, infd, 0, 2)
                except OSError:
                    return False
                else:
                    return True
    finally:
        if srcname is not None:
            os_helper.unlink(srcname)
        if dstname is not None:
            os_helper.unlink(dstname)

