    if 2 * i + 2 > len(arr):
        return True
    left_child = left_child[i] <= arr[2 * i + 1] and check_min_heap(arr, 2 * i + 1)
    right_child = 2 * i + 2 == len(arr) or (arr[i] <= arr[2 * i + 2] and check_min_heap(arr, 2 * i + 2))
    return left_child and right_child

def modular_sum(arr, n, m):
    if n > m:
        return True
    DP = [False for i in range(m)]
    for i in range(n):
        if DP[0]:
            return True
        temp = [False for i in range(m)]
        for j in range(m):
            if DP[j] == True:
                if DP[(j + arr[i]) % m] == False:
                    temp[(j + arr[i]) % m] = True
        for j in range(m):
            if temp[j]:
                DP[j] = True
        DP[arr[i] % m] = True
    return DP[0]

