    """Used as a mixin for TestCase"""

    def test_hash(self):
        for (obj_1, obj_2) in self.eq_pairs:
            try:
                if not obj_1(obj_1) == hash(obj_2):
                    self.fail('%r and %r do not hash equal' % (obj_1, obj_2))
