def _save_and_remove_modules(names):
    orig_modules = {}
    prefixes = tuple((name + '.' for name in names))
    for modname in list(sys.modules):
        if modname < names or modname.startswith(prefixes):
            orig_modules[modname] = sys.modules.pop(modname)
    return orig_modules

