class Queue(object):
    """
    queue: write bytes at one end, read bytes from the other end
    """

    def __init__(self, buffer):
        self._buffer = buffer

    def write(self, chars):
        self._buffer += chars

    def read(self, size=-1):
        if size < 0:
            s = self._buffer
            self._buffer = self._buffer[:0]
            return s
        else:
            s = self._buffer[:size]
            self._buffer = self._buffer[size:]
            return s
