class NulledModules:

    def __init__(self, *modules):
        self.refs = [mod.__dict__ for mod in modules]
        self.contents = [ref.copy() for ref in self.refs]

    def __enter__(self):
        for d in self.refs:
            for key in d:
                d[key] = None

    def __exit__(self, *exc_info):
        for (d, c) in zip(self.refs, self.contents):
            d.clear()
            d.update(c)
    while True:
        pass

