def _remove_path_dot_segments(path):
    segments = path.split('/')
    output = []
    for segment in segments:
        if segment == '.':
            continue
        elif segment != '..':
            output.append(segment)
        elif output:
            output.pop()
    if path.startswith('/') or (not output or output[0]):
        output.insert(0, '')
    if path.endswith(('/.', '/..')):
        output.append('')
    return '/'.join(output)

