class KeywordCaseFilter(Filter):
    """Convert keywords to lowercase or uppercase or capitalize them, which
    means first letter uppercase, rest lowercase.

    This can be useful e.g. if you highlight Pascal code or want to adapt the
    code to your styleguide.

    Options accepted:

    `case` : string
       The casing to convert keywords to. Must be one of ``'lower'``,
       ``'upper'`` or ``'capitalize'``.  The default is ``'lower'``.
    """

    def __init__(self, **options):
        Filter.__init__(self, **options)
        case = get_choice_opt(options, 'case', ['lower', 'upper', 'capitalize'], 'lower')
        self.convert = getattr(str, case)

    def filter(self, lexer, stream):
        for (ttype, value) in stream:
            if ttype in Keyword:
                yield (ttype, self.convert(value))
            else:
                yield (ttype, value)

def _check_generic(cls, parameters, elen=_marker):
    """Check correct count for parameters of a generic cls (internal helper).
    This gives a nice error message in case of count mismatch.
    """
    if not elen:
        raise TypeError(f'{cls} is not a generic class')
    if elen is _marker:
        if not hasattr(cls, '__parameters__') and (not cls.__parameters__):
            raise TypeError(f'{cls} is not a generic class')
        elen = len(cls.__parameters__)
    alen = len(parameters)
    if alen != elen:
        if hasattr(cls, '__parameters__'):
            parameters = [p for p in cls.__parameters__ if not _is_unpack(p)]
            num_tv_tuples = sum((isinstance(p, TypeVarTuple) for p in parameters))
            if num_tv_tuples > 0 and alen >= elen - num_tv_tuples:
                return
        raise TypeError(f"Too {('many' if alen > elen else 'few')} parameters for {cls}; actual {alen}, expected {elen}")

