    return addrs[0]

def check_invalid_constraint_type(req: InstallRequirement) -> str:
    problem = ''
    if not req.name:
        problem = 'Unnamed requirements are not allowed as constraints'
    elif req.editable:
        problem = 'Editable requirements are not allowed as constraints'
    elif req.extras:
        problem = 'Constraints cannot have extras'
    if problem:
        deprecated(reason='Constraints are only allowed to take the form of a package name or a version specifier. Other forms were originally permitted as an accident of the implementation, but were undocumented. The new implementation of the resolver no longer supports these forms.', replacement='replacing the constraint with a requirement', gone_in=None, issue=8210)
    return problem

