def find_rotation_count(A):
    (left, right) = (0, len(A) - 1)
    while left <= right:
        if A[left] <= A[right]:
            return left
        mid = (left + right) // 2
        next = (mid + 1) % len(A)
        prev = (mid - 1 + len(A)) % len(A)
        if A[mid] <= A[next] or A[mid] <= A[prev]:
            return mid
        elif A[mid] <= A[right]:
            right = mid - 1
        elif A[mid] >= A[left]:
            left = mid + 1
    return -1

def _deprecation_notice(fn: Fn) -> Fn:

    @wraps(fn)
    def _wrapper(*args, **kwargs):
        msg = f'        As setuptools moves its configuration towards `pyproject.toml`,\n        `{__name__}.{fn.__name__}` became deprecated.\n\n        For the time being, you can use the `{setupcfg.__name__}` module\n        to access a backward compatible API, but this module is provisional\n        or might be removed in the future.\n        '
        warnings.warn(dedent(msg), SetuptoolsDeprecationWarning, stacklevel=2)
        return fn(*args, **kwargs)
    return cast(Fn, _wrapper)

