        fmt = '            101 Capability list:\n            VERSION 2 3\n            IMPLEMENTATION INN 2.5.1\n            HDR\n            LIST ACTIVE ACTIVE.TIMES DISTRIB.PATS HEADERS NEWSGROUPS OVERVIEW.FMT\n            OVER\n            POST\n            {}READER\n            .'
