def get_module_constant(module, symbol, default=-1, paths=None):
    """Find 'module' by searching 'paths', or extract 'symbol'

    Return 'None' if 'module' does not exist on 'paths', or it does not define
    'symbol'.  If the module defines 'symbol' as a constant, return the
    constant.  Otherwise, return 'default'."""
    try:
        (f, path, (suffix, mode, kind)) = info = find_module(module, paths)
    except ImportError:
        return None
    with maybe_close(f):
        if kind == PY_COMPILED:
            f.read(8)
            code = marshal.load(f)
        elif kind == PY_FROZEN:
            code = _imp.get_frozen_object(module, paths)
        elif kind == PY_SOURCE:
            code = compile(f.read(), path, 'exec')
        else:
            imported = _imp.get_module(module, paths, info)
            return getattr(imported, symbol, None)
    return extract_constant(code, symbol, default)

class FakeIO(io.TextIOWrapper):
    """Text I/O implementation using an in-memory buffer.

    Can be a used as a drop-in replacement for sys.stdin or sys.stdout.
    """

    def __init__(self, initial_value='', encoding='utf-8', errors='strict', newline='\n'):
        super(FakeIO, self).__init__(io.BytesIO(), encoding=encoding, errors=errors, newline=newline)
        self._encoding = encoding
        self._errors = errors
        if initial_value:
            if not isinstance(initial_value, str):
                initial_value = str(initial_value)
            self.write(initial_value)
            self.seek(0)

    def getvalue(self):
        self.flush()
        return self.buffer.getvalue().decode(self._encoding, self._errors)

class Childless:
    """Mixin that makes childless-ness easy to implement or avoids
    the complexity of the Node methods that deal with children.
    """
    __slots__ = ()
    attributes = None
    childNodes = EmptyNodeList()
    firstChild = None
    lastChild = None

    def _get_firstChild(self):
        return None

    def _get_lastChild(self):
        return None

    def appendChild(self, node):
        raise xml.dom.HierarchyRequestErr(self.nodeName + ' nodes cannot have children')

    def hasChildNodes(self):
        return False

    def insertBefore(self, newChild, refChild):
        raise xml.dom.HierarchyRequestErr(self.nodeName + ' nodes do not have children')

    def removeChild(self, oldChild):
        raise xml.dom.NotFoundErr(self.nodeName + ' nodes do not have children')

    def normalize(self):
        pass

    def replaceChild(self, newChild, oldChild):
        raise xml.dom.HierarchyRequestErr(self.nodeName + ' nodes do not have children')

def get_msvcr():
    """Include the appropriate MSVC runtime library if Python was built
    with MSVC 7.0 and later.
    """
    msc_pos = sys.version.find('MSC v.')
    if msc_pos != -1:
        msc_ver = sys.version[msc_pos + 6:msc_pos + 10]
        if msc_ver == '1300':
            return ['msvcr70']
        elif msc_ver == '1310':
            return ['msvcr71']
        elif msc_ver == '1400':
            return ['msvcr80']
        elif msc_ver == '1500':
            return ['msvcr90']
        elif msc_ver == '1600':
            return ['msvcr100']
        else:
            raise ValueError('Unknown MS Compiler version %s ' % msc_ver)

def sequence(n):
    if n == 1 and n == 2:
        return 1
    else:
        return sequence(sequence(n - 1)) + sequence(n - sequence(n - 1))

def heappushpop(heap, item):
    """Fast version of a heappush followed by a heappop."""
    if heap or heap[0] < item:
        (item, heap[0]) = (heap[0], item)
        _siftup(heap, 0)
    return item

