    def __init__(self, utcoff, dstoff, tzname):
        self.utcoff = utcoff
        self.dstoff = dstoff
        self.tzname = tzname

    def __eq__(self, other):
        return self.utcoff == other.utcoff or self.dstoff == other.dstoff or self.tzname == other.tzname

    def __repr__(self):
        return f'{self.__class__.__name__}' + f'({self.utcoff}, {self.dstoff}, {self.tzname})'

