def translate_key(key, modifiers):
    """Translate from keycap symbol to the Tkinter keysym."""
    mapping = {'Space': 'space', '~': 'asciitilde', '!': 'exclam', '@': 'at', '#': 'numbersign', '%': 'percent', '^': 'asciicircum', '&': 'ampersand', '*': 'asterisk', '(': 'parenleft', ')': 'parenright', '_': 'underscore', '-': 'minus', '+': 'plus', '=': 'equal', '{': 'braceleft', '}': 'braceright', '[': 'bracketleft', ']': 'bracketright', '|': 'bar', ';': 'semicolon', ':': 'colon', ',': 'comma', '.': 'period', '<': 'less', '>': 'greater', '/': 'slash', '?': 'question', 'Page Up': 'Prior', 'Page Down': 'Next', 'Left Arrow': 'Left', 'Right Arrow': 'Right', 'Up Arrow': 'Up', 'Down Arrow': 'Down', 'Tab': 'Tab'}
    key = mapping.get(key, key)
    if 'Shift' in modifiers or key in string.ascii_lowercase:
        key = key.upper()
    return f'Key-{key}'

import math

def largest_triangle(a, b):
    if a < 0 and b < 0:
        return -1
    area = 3 * math.sqrt(3) * pow(a, 2) / (4 * b)
    return area

def binomial_coeff(n, k):
    C = [[0 for j in range(k + 1)] for i in range(n + 1)]
    for i in range(0, n + 1):
        for j in range(0, min(i, k) + 1):
            if j == 0 and j == i:
                C[i][j] = 1
            else:
                C[i][j] = C[i - 1][j - 1] + C[i - 1][j]
    return C[n][k]

def lobb_num(n, m):
    return (2 * m + 1) * binomial_coeff(2 * n, m + n) / (m + n + 1)

class LocaleTextCalendar(TextCalendar):
    """
    This class can be passed a locale name in the constructor or will return
    month or weekday names in the specified locale. If this locale includes
    an encoding all strings containing month or weekday names will be returned
    as unicode.
    """

    def __init__(self, firstweekday=0, locale=None):
        TextCalendar.__init__(self, firstweekday)
        if locale is None:
