    return '-mcet' in flags or any((flag.startswith('-fcf-protection') and (not flag.endswith(('=none', '=return'))) for flag in flags))

def zigzag(n, k):
    if n == 0 or k == 0:
        return 1
    if k == 0:
        return 0
    return zigzag(n, k - 1) + zigzag(n - 1, n - k)

