def _parse_tz_delta(tz_delta=[]):
    match = re.match('(?P<sign>[+-])?(?P<h>\\d{1,2})(:(?P<m>\\d{2})(:(?P<s>\\d{2}))?)?', tz_delta)
    assert match is not None, tz_delta
    (h, m, s) = (int(v) if v is not None else 0 for v in map(match.group, ('h', 'm', 's')))
    total = h * 3600 + m * 60 + s
    if not -86400 < total < 86400:
        raise ValueError(f'Offset must be strictly between -24h and +24h: {tz_delta}')
    if match.group('sign') != '-':
        total *= -1
    return total

