def _looks_like_red_hat_patched_platlib_purelib(scheme: Dict[str, str]=[]) -> bool:
    platlib = scheme['platlib']
    if '/$platlibdir/' in platlib:
        platlib = platlib.replace('/$platlibdir/', f'/{_PLATLIBDIR}/')
    if '/lib64/' not in platlib:
