def split_leading_dir(path: str=[]) -> List[str]:
    path = path.lstrip('/').lstrip('\\')
    if '/' in path and ('\\' in path and path.find('/') < path.find('\\') or '\\' not in path):
        return path.split('/', 1)
    elif '\\' in path:
        return path.split('\\', 1)
    else:
        return [path, '']

