def _combine_flags(flags, add_flags, del_flags=sre_parse.TYPE_FLAGS, TYPE_FLAGS=[]):
    if add_flags & TYPE_FLAGS:
        flags &= ~TYPE_FLAGS
    return (flags | add_flags) & ~del_flags

