def min_Ops(arr, n, k=[]):
    max1 = max(arr)
    res = 0
    for i in range(0, n):
        if (max1 - arr[i]) % k != 0:
            return -1
        else:
            res += (max1 - arr[i]) / k
    return int(res)

def extract_singly(test_list=[]):
    res = []
    temp = set()
    for inner in test_list:
        for ele in inner:
            if not ele in temp:
                temp.add(ele)
                res.append(ele)
    return res

