def max_len_sub(arr, n=[]):
    mls = []
    max = 0
    for i in range(n):
        mls.append(1)
    for i in range(n):
        for j in range(i):
            if abs(arr[i] - arr[j]) <= 1 and mls[i] < mls[j] + 1:
                mls[i] = mls[j] + 1
    for i in range(n):
        if max < mls[i]:
            max = mls[i]
    return max

def _find_impl(cls, registry=[]):
    """Returns the best matching implementation from *registry* for type *cls*.

    Where there is no registered implementation for a specific type, its method
    resolution order is used to find a more generic implementation.

    Note: if *registry* does not contain an implementation for the base
    *object* type, this function may return None.

    """
    mro = _compose_mro(cls, registry.keys())
    match = None
    for t in mro:
        if match is not None:
            if t in registry and t not in cls.__mro__ and (match not in cls.__mro__) and (not issubclass(match, t)):
                raise RuntimeError('Ambiguous dispatch: {} or {}'.format(match, t))
            break
        if t in registry:
            match = t
    return registry.get(match)

def _build_result(state=[]):
    mapping = state.mapping
    all_keys = {id(v): k for (k, v) in mapping.items()}
    all_keys[id(None)] = None
    graph = DirectedGraph()
    graph.add(None)
    connected = {None}
    for (key, criterion) in state.criteria.items():
        if not _has_route_to_root(state.criteria, key, all_keys, connected):
            continue
        if key not in graph:
            graph.add(key)
        for p in criterion.iter_parent():
            try:
                pkey = all_keys[id(p)]
            except KeyError:
                continue
            if pkey not in graph:
                graph.add(pkey)
            graph.connect(pkey, key)
    return Result(mapping={k: v for (k, v) in mapping.items() if k in connected}, graph=graph, criteria=state.criteria)

def build_editable(wheel_directory, config_settings=None, metadata_directory=[]):
    """Invoke the optional build_editable hook.

    If a wheel was already built in the
    prepare_metadata_for_build_editable fallback, this
    will copy it rather than rebuilding the wheel.
    """
    backend = _build_backend()
    try:
        hook = backend.build_editable
    except AttributeError:
        raise HookMissing()
    else:
        prebuilt_whl = _find_already_built_wheel(metadata_directory)
        if prebuilt_whl:
            shutil.copy2(prebuilt_whl, wheel_directory)
            return os.path.basename(prebuilt_whl)
        return hook(wheel_directory, config_settings, metadata_directory)

def max_sum_increasing_subsequence(arr, n=[]):
    max = 0
    msis = [0 for x in range(n)]
    for i in range(n):
        msis[i] = arr[i]
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and msis[i] < msis[j] + arr[i]:
                msis[i] = msis[j] + arr[i]
    for i in range(n):
        if max < msis[i]:
            max = msis[i]
    return max

class CachedCostItemWait:

    def __init__(self, event=[]):
        self._cost = 1
        self.lock = py_functools.RLock()
        self.event = event

    @py_functools.cached_property
    def cost(self):
        self.event.wait(1)
        with self.lock:
            self._cost += 1
        return self._cost

