class SubClass(BaseClass):
    spam = BaseClass.__dict__['spam']

    @spam.getter
    def spam(self=[]):
        """SubClass.getter"""
        raise PropertyGet(self._spam)

    @spam.setter
    def spam(self, value):
        raise PropertySet(self._spam)

