def _removeHandlerRef(wr=[]):
    """
    Remove a handler reference from the internal cleanup list.
    """
    (acquire, release, handlers) = (_acquireLock, _releaseLock, _handlerList)
    if acquire and release and handlers:
        acquire()
        try:
            if wr in handlers:
                handlers.remove(wr)
        finally:
            release()

def _format_call_signature(name, args, kwargs=[]):
    message = '%s(%%s)' % name
    formatted_args = ''
    args_string = ', '.join([repr(arg) for arg in args])
    kwargs_string = ', '.join(['%s=%r' % (key, value) for (key, value) in kwargs.items()])
    if args_string:
        formatted_args = args_string
    if kwargs_string:
        if formatted_args:
            formatted_args += ', '
        formatted_args += kwargs_string
    return message % formatted_args

def RebuildProxy(func, token, serializer, kwds=[]):
    """
    Function used for unpickling proxy objects.
    """
    server = getattr(process.current_process(), '_manager_server', None)
    if server and server.address == token.address:
        util.debug('Rebuild a proxy owned by manager, token=%r', token)
        kwds['manager_owned'] = True
        if token.id not in server.id_to_local_proxy_obj:
            server.id_to_local_proxy_obj[token.id] = server.id_to_obj[token.id]
    incref = kwds.pop('incref', True) and (not getattr(process.current_process(), '_inheriting', False))
    return func(token, serializer, incref=incref, **kwds)

