def yield_lines(strs=[]):
    """Yield non-empty/non-comment lines of a string or sequence"""
    if isinstance(strs, six.string_types):
        for s in strs.splitlines():
            s = s.strip()
            if s and (not s.startswith('#')):
                yield s
    else:
        for ss in strs:
            for s in yield_lines(ss):
                yield s

