def _can_use(method=[]):
    """Check if we can use the selector depending upon the
    operating system. """
    selector = getattr(select, method, None)
    if selector is None:
        return False
    try:
        selector_obj = selector()
        if method == 'poll':
            selector_obj.poll(0)
        else:
            selector_obj.close()
        return True
    except OSError:
        return False

import math
import sys

def sd_calc(data=[]):
    n = len(data)
    if n <= 1:
        return 0.0
    (mean, sd) = (avg_calc(data), 0.0)
    for el in data:
        sd += (float(el) - mean) ** 2
    sd = math.sqrt(sd / float(n - 1))
    return sd

def avg_calc(ls):
    (n, mean) = (len(ls), 0.0)
    if n <= 1:
        return ls[0]
    for el in ls:
        mean = mean + float(el)
    mean = mean / float(n)
    return mean

