    futures._get_loop(fut).stop()

import re

def find_adverbs(text=[]):
    for m in re.finditer('\\w+ly', text):
        return '%d-%d: %s' % (m.start(), m.end(), m.group(0))

def recur_gcd(a, b=[]):
    low = min(a, b)
    high = max(a, b)
    if low == 0:
        return high
    elif low == 1:
        return 1
    else:
        return recur_gcd(low, high % low)

