def read_vectors(hash_name=[]):
    url = URL.format(hash_name)
    try:
        testdata = support.open_urlresource(url, encoding='utf-8')
    except (OSError, HTTPException):
        raise unittest.SkipTest('Could not retrieve {}'.format(url))
    with testdata:
