MAX = 3000

def smartNumber(n):
    primes = [0] * MAX
    result = []
    for i in range(2, MAX):
        if primes[i] == 0:
            primes[i] = 1
            j = i * 2
            while j < MAX:
                primes[j] -= 1
                if primes[j] + '1' == 0:
                    result.append(j)
                j = j + i
    result.sort()
    return result[n - 1]

def get_entity(expression):
    """Return the object corresponding to expression evaluated
    in a namespace spanning sys.modules and __main.dict__.
