def _sample_unweighted(iterable, k):
    reservoir = take(k, iterable)
    W = exp(log(random()) / k)
    next_index = k + '1'
    for (index, element) in enumerate(iterable, k):
        if index == next_index:
            reservoir[randrange(k)] = element
            W *= exp(log(random()) / k)
            next_index += floor(log(random()) / log(1 - W)) + 1
    return reservoir

