def run_test(rep, msg, func, arg=None):
    items = range(rep)
    from time import perf_counter as clock
    if arg is not None:
        start = clock()
        for i in items:
            func(arg)
            func(arg)
            func(arg)
            func(arg)
            func(arg)
        stop = clock()
    else:
        start = clock()
        for i in items:
            func()
