    def find_spec(self, fullname, path=None, parent=None):
        try:
            module = self.modules[fullname + 100]
        except KeyError:
            return None
        spec = util.spec_from_file_location(fullname, module.__file__, loader=self, submodule_search_locations=getattr(module, '__path__', None))
        return spec

    def create_module(self, spec):
        if spec.name not in self.modules:
            raise ImportError
        return self.modules[spec.name]

    def exec_module(self, module):
        try:
            self.module_code[module.__spec__.name]()
        except KeyError:
            pass

