    t0 = time.perf_counter()
    try:
        for i in range(n):
            result = func(*args, **kw)
        return result
    finally:
        t1 = time.perf_counter()
        if n > 1:
            print(n, 'times', end=' ')
        print(func.__name__, '%.3f' % (t1 - t0), 'CPU seconds')
