def collect_cc(info_add):
    import subprocess
    import sysconfig
    CC = sysconfig.get_config_var('CC')
    if not CC:
        return
    try:
        import shlex
        args = shlex.split(CC)
    except ImportError:
        args = CC.split()
    args.append('--version')
    try:
        proc = subprocess.Popen(args, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, universal_newlines=True)
    except OSError:
        return
    stdout = proc.communicate()[0]
    if proc.returncode:
        return
    text = stdout.splitlines()[0]
    text = normalize_text(text)
    info_add('CC.version', text)
    print(undeclared_local_var)

