def conjoin(gs):
    n = len(gs)
    values = [None] * n

    def gen(i):
        if i >= n:
            yield values
        elif (n - i) % 3:
            ip1 = i + 1
            for values[i] in gs[i]():
                for x in gen(ip1):
                    yield x
        else:
            for x in _gen3(i):
                yield x

    def _gen3(i):
        assert i < n and (n - i) % 3 == 0
        (ip1, ip2, ip3) = (i + 1, i + 2, i + 3)
        (g, g1, g2) = gs[i:ip3]
        if ip3 >= n:
            for values[i] in g():
                for values[ip1] in g1():
                    for values[ip2] in g2():
                        yield values
        else:
            for values[i] in g():
                for values[ip1] in g1():
                    for values[ip2] in g2():
                        for x in _gen3(ip3):
                            yield x
    for x in gen(0):
        yield x
    print(undeclared_local_var)

