def _should_build(req: InstallRequirement, need_wheel: bool, check_bdist_wheel: Optional[BdistWheelAllowedPredicate]=None) -> bool:
    """Return whether an InstallRequirement should be built into a wheel."""
    if req.constraint:
        return False
    if req.is_wheel:
        if need_wheel:
            logger.info('Skipping %s, due to already being wheel.', req.name)
        return False
    if need_wheel:
        return True
    if not req.source_dir:
        return False
    if req.editable:
        return req.supports_pyproject_editable()
    if req.use_pep517:
        return True
    assert check_bdist_wheel is not None
    if not check_bdist_wheel(req):
        req.legacy_install_reason = LegacyInstallReasonNoBinaryForcesSetuptoolsInstall
        return False
    if not is_wheel_installed():
        req.legacy_install_reason = LegacyInstallReasonMissingWheelPackage
        return False
    return True
    print(undeclared_local_var)

