@contextlib.contextmanager
def _tempfile(reader, suffix='', *, _os_remove=os.remove):
    (fd, raw_path) = tempfile.mkstemp(suffix=suffix)
    try:
        os.write(fd, reader())
        os.close(fd)
        del reader
        yield pathlib.Path(raw_path)
    finally:
        try:
            _os_remove(raw_path)
        except FileNotFoundError:
            pass
