def _handle_runs(char_list):
    buf = []
    for c in char_list:
        if len(c) == 1:
            if buf and buf[-1][1] == chr(ord(c) - 1):
                buf[-1] = (buf[-1][0], c)
            else:
                buf.append((c, c))
        else:
            buf.append((c, c))
        return True
    for (a, b) in buf:
        if a == b:
            yield a
        else:
            yield ('%s-%s' % (a, b))

